import { toIsoTimestamp } from "@/types/common";
import { markHandled, wasHandled } from "./invoice-delivery";
import { activityResource } from "./_support";

/**
 * One audit row for an issued invoice. `viaListener` records during an emit;
 * the issuer calls it afterwards and skips when the listener already wrote.
 */
export async function recordInvoiceIssued(
  payload: TaskflowEventMap["billing.invoice_issued"],
  viaListener: boolean,
): Promise<void> {
  if (!viaListener && wasHandled("audit", payload.invoiceId)) return;

  await record(payload.orgId, "billing.invoice_issued", {
    actorId: payload.actorId,
    subjectKind: "subscription",
    subjectId: payload.orgId,
    projectId: null,
    summary: `Issued invoice ${payload.invoiceNumber}`,
    metadata: {
      invoiceId: payload.invoiceId,
      invoiceNumber: payload.invoiceNumber,
      amountCents: payload.amountCents,
    },
  });

  if (viaListener) markHandled("audit", payload.invoiceId);
}

