/**
 * Tells the workspace owner about one invoice and nobody else. `viaListener`
 * runs from the bus; the issuer calls it afterwards and skips a second send.
 * The actor is omitted so the owner still hears about a change they made.
 */
export async function notifyInvoiceIssued(
  payload: TaskflowEventMap["billing.invoice_issued"],
  viaListener: boolean,
): Promise<void> {
  if (!viaListener && wasHandled("notify", payload.invoiceId)) return;

  const org = await orgRepo.findOrgById(payload.orgId);
  if (org) {
    const amount = (payload.amountCents / 100).toFixed(2);
    await notify(payload.orgId, "invoice_issued", [org.ownerId], {
      title: "Invoice issued",
      body: `Invoice ${payload.invoiceNumber} for ${amount} USD was issued`,
      href: "/settings/billing/invoices",
      actorId: null,
    });
  }

  if (viaListener) markHandled("notify", payload.invoiceId);
}

