  const plan = await planFor(input.orgId);

  if (input.seats > getLimit(plan, "seats")) {
    throw new Error(`Plan ${plan} tops out at ${getLimit(plan, "seats")} seats`);
  }

  const existing = await subscriptionRepo.findSubscription(input.orgId);
  const updated = await subscriptionRepo.updateSeatCount(input.orgId, input.seats);

  if (
    existing &&
    existing.status === "active" &&
    isPaidPlan(existing.plan) &&
    input.seats > existing.seats
  ) {
    const now = new Date();
    const full =
      getPlanLimits(existing.plan).priceCentsPerSeatMonthly *
      (input.seats - existing.seats) *
      monthsInPeriod(existing.interval);
    const amountCents = prorateCents(
      full,
      daysRemaining(now, parseIso(existing.currentPeriodEnd)),
      daysInPeriod(
        parseIso(existing.currentPeriodStart),
        parseIso(existing.currentPeriodEnd),
      ),
    );
    await issueSubscriptionInvoice({
      orgId: input.orgId,
      amountCents,
      periodStart: existing.currentPeriodStart,
      periodEnd: existing.currentPeriodEnd,
      actorId: actor.userId,
      occurredAt: toIsoTimestamp(now),
    });
  }

  return updated;
}

export type IssueSubscriptionInvoiceInput = {
  orgId: OrgId;
  amountCents: number;
  periodStart: IsoTimestamp;
  periodEnd: IsoTimestamp;
  actorId: UserId | null;
  occurredAt: IsoTimestamp;
};

/**
 * Persists one invoice and announces it once: the domain event, one audit row
 * (subject is the workspace) and one notification to the workspace owner.
 * A charge of zero cents produces no invoice.
 */
export async function issueSubscriptionInvoice(
  input: IssueSubscriptionInvoiceInput,
): Promise<Invoice | null> {
  if (input.amountCents <= 0) return null;

  const sequence = (await invoiceRepo.countInvoices(input.orgId)) + 1;
  const invoice = await invoiceRepo.insertInvoice(input.orgId, {
    orgId: input.orgId,
    number: `INV-${String(sequence).padStart(4, "0")}`,
    amountCents: input.amountCents,
    currency: "usd",
    periodStart: input.periodStart,
    periodEnd: input.periodEnd,
    paidAt: null,
  });

  const payload = {
    orgId: input.orgId,
    actorId: input.actorId,
    occurredAt: input.occurredAt,
    invoiceId: invoice.id,
    invoiceNumber: invoice.number,
    amountCents: invoice.amountCents,
    periodStart: invoice.periodStart,
    periodEnd: invoice.periodEnd,
  };

  beginAnnounce(invoice.id);
  try {
    await emit("billing.invoice_issued", payload);
    await recordInvoiceIssued(payload, false);
    await notifyInvoiceIssued(payload, false);
  } finally {
    endAnnounce(invoice.id);
  }

  return invoice;
}

