/**
 * Renews subscriptions whose period has ended and ends cancellations that are due.
 *
 * Every renewed paid period is invoiced in full at the seat count of that
 * moment. Free periods move forward without an invoice. A cancellation takes
 * effect on its date by moving the workspace to the free plan. Trialing and
 * past-due subscriptions are left for the trial-expiry job. Archived
 * workspaces are skipped. Running the job again at the same instant changes
 * nothing.
 *
 * Must call (do not reimplement): emit, getPlanLimits
 */
import { getPlanLimits } from "@/config/plan-limits";
import { addBillingPeriod, fullPeriodCents } from "@/lib/billing-period";
import { parseIso } from "@/lib/date";
import { emit } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import { isArchived } from "@/lib/soft-delete";
import * as invoiceRepo from "@/server/repositories/invoice-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import { issueSubscriptionInvoice } from "@/server/services/billing-service";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { Subscription } from "@/types/billing";

const logger = createLogger("billing-renewal-job");

/**
 * One pass over every workspace subscription. `now` is the clock the caller
 * supplies; period boundaries and events are stamped from it.
 */
export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    const subscriptions = await subscriptionRepo.listSubscriptions();
    const occurredAt = toIsoTimestamp(now);

    for (const subscription of subscriptions) {
      try {
        const changed = await renewSubscription(subscription, now, occurredAt);
        if (changed) result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("billing renewal failed", {
          orgId: subscription.orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

async function renewSubscription(
  subscription: Subscription,
  now: Date,
  occurredAt: ReturnType<typeof toIsoTimestamp>,
): Promise<boolean> {
  const org = await orgRepo.findOrgById(subscription.orgId);
  if (!org || isArchived(org)) return false;

  if (subscription.status === "trialing" || subscription.status === "past_due") {
    return false;
  }

  let current = subscription;
  let changed = false;

  if (current.status === "canceled") {
    if (current.cancelAt === null) return false;
    if (parseIso(current.cancelAt).getTime() > now.getTime()) return false;

    const from = current.plan;
    const start = parseIso(current.cancelAt);
    const end = addBillingPeriod(start, "monthly");
    current = await subscriptionRepo.settleCancellation(
      current.orgId,
      toIsoTimestamp(start),
      toIsoTimestamp(end),
      occurredAt,
    );

    await emit("billing.plan_changed", {
      orgId: current.orgId,
      actorId: null,
      occurredAt,
      from,
      to: "free",
    });
    changed = true;
  }

  if (current.status !== "active") return changed;

  let periodEnd = parseIso(current.currentPeriodEnd);

  while (periodEnd.getTime() <= now.getTime()) {
    const nextStart = periodEnd;
    const nextEnd = addBillingPeriod(nextStart, current.interval);
    const periodStart = toIsoTimestamp(nextStart);
    const nextPeriodEnd = toIsoTimestamp(nextEnd);
    const amountCents = fullPeriodCents(
      current.plan,
      current.seats,
      current.interval,
    );

    // Touch the plan catalogue so a price change is picked up from getPlanLimits.
    getPlanLimits(current.plan);

    if (
      amountCents > 0 &&
      !(await invoiceRepo.invoiceExistsForPeriod(
