{"type":"ReadFile","FileContent":{"content":"1→/**
 * Billing-period arithmetic shared by renewals and mid-period charges.
 *
 * A monthly period ends on the same day of the following month, or on that
 * month's last day when the day does not exist. An annual period ends on the
 * same day and month of the following year. The next period starts exactly
 * where the previous one ended, so a clamped day carries forward.
 */
import { getPlanLimits } from "@/config/plan-limits";
10→import type { BillingInterval, PlanId } from "@/types/billing";

const DAY_MS = 24 * 60 * 60 * 1000;

export function monthsInPeriod(interval: BillingInterval): number {
  return interval === "annual" ? 12 : 1;
}

/** Full charge for one period, in cents. Free plans return zero. */
export function fullPeriodCents(
20→  plan: PlanId,
  seats: number,
  interval: BillingInterval,
): number {
  return (
    getPlanLimits(plan).priceCentsPerSeatMonthly * seats * monthsInPeriod(interval)
  );
}

export function isPaidPlan(plan: PlanId): boolean {
30→  return getPlanLimits(plan).priceCentsPerSeatMonthly > 0;
}

/** Advance `start` by one billing interval, preserving the time of day in UTC. */
export function addBillingPeriod(start: Date, interval: BillingInterval): Date {
  const months = monthsInPeriod(interval);
  const year = start.getUTCFullYear();
  const month = start.getUTCMonth();
  const absoluteMonth = month + months;
  const targetYear = year + Math.floor(absoluteMonth / 12);
40→  const targetMonth = absoluteMonth % 12;
  const lastDay = new Date(Date.UTC(targetYear, targetMonth + 1, 0)).getUTCDate();
  const targetDay = Math.min(start.getUTCDate(), lastDay);

  return new Date(
    Date.UTC(
      targetYear,
      targetMonth,
      targetDay,
      start.getUTCHours(),
50→      start.getUTCMinutes(),
      start.getUTCSeconds(),
      start.getUTCMilliseconds(),
    ),
  );
}

/**
 * Whole days from `start` up to `end`, rounded to the nearest day and never
 * less than one. Calendar periods land on exact day counts; the floor exists
60→ * so a zero-length span cannot divide a proration by zero.
 */
export function daysInPeriod(start: Date, end: Date): number {
  return Math.max(1, Math.round((end.getTime() - start.getTime()) / DAY_MS));
}

/**
 * Whole or started days from `now` until `end`. Fourteen days and twenty-two
 * hours count as fifteen. Once `end` has been reached there are none left.
 */
70→export function daysRemaining(now: Date, end: Date): number {
  const remaining = end.getTime() - now.getTime();
  if (remaining <= 0) return 0;
  return Math.ceil(remaining / DAY_MS);
}

/** Scale a full-period charge by the fraction of the period still ahead, in whole cents. */
export function prorateCents(
  fullCents: number,
  daysLeft: number,
80→  periodDays: number,
): number {
  if (fullCents <= 0 || daysLeft <= 0 || periodDays <= 0) return 0;
  return Math.floor((fullCents * daysLeft) / periodDays);
}
