/**
 * The one place a quota is evaluated. Every guard elsewhere calls this rather
 * than reading `PLAN_LIMITS` itself, so a new plan dimension needs changing in
 * exactly two files: `plan-limits.ts` and `usageFor()` below.
 */
export async function checkLimit(
  orgId: OrgId,
  resource: LimitedResource,
  requested = 1,
): Promise<LimitCheck> {
  const plan = await planFor(orgId);
  const used = await usageFor(orgId, resource);
  const limit = getLimit(plan, resource);

  return {
    resource,
    plan,
    limit,
    used,
    remaining: Math.max(0, limit - used),
    exceeded: wouldExceedLimit(plan, resource, used, requested),
  };
}

/** Throwing form used by the create paths, and it emits the breach event. */
export async function assertWithinLimit(
  orgId: OrgId,
  resource: LimitedResource,
  requested = 1,
): Promise<void> {
  const check = await checkLimit(orgId, resource, requested);
  if (!check.exceeded) return;

  await emit("billing.limit_exceeded", {
    orgId,
    actorId: null,
    occurredAt: toIsoTimestamp(new Date()),
    resource,
    limit: check.limit,
    used: check.used,
  });

  throw new Error(
    `Plan ${check.plan} allows ${check.limit} ${resource}; ${check.used} are in use`,
  );
}

/**
 * A downgrade is refused while the org is over the target plan's quota — the
 * alternative is silently breaking their workspace at the next write.
 */
export async function changePlan(
  actor: Actor,
  input: ChangePlanInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const currentPlan = await planFor(input.orgId);

  for (const resource of SUMMARY_RESOURCES) {
    const used = await usageFor(input.orgId, resource);
    if (wouldExceedLimit(input.plan, resource, used, 0)) {
      throw new Error(
        `Cannot move to ${input.plan}: ${used} ${resource} exceeds its limit of ${getLimit(input.plan, resource)}`,
      );
    }
  }

  const existing = await subscriptionRepo.findSubscription(input.orgId);
  const now = new Date();
  let subscription: Subscription;

  if (existing?.status === "trialing") {
    // Choosing a plan during a trial keeps that period and charges nothing.
    // Status becomes active so the first invoice is the renewal when it ends.
    subscription = await subscriptionRepo.updateSubscriptionPlan(
      input.orgId,
      input.plan,
      input.interval,
    );
  } else if (existing && currentPlan === "free" && input.plan !== "free") {
    const periodStart = toIsoTimestamp(now);
    const periodEnd = toIsoTimestamp(addBillingPeriod(now, input.interval));
    subscription = await subscriptionRepo.beginPaidPeriod(
      input.orgId,
      input.plan,
      input.interval,
      periodStart,
      periodEnd,
    );
    await issueSubscriptionInvoice({
      orgId: input.orgId,
      amountCents: fullPeriodCents(input.plan, existing.seats, input.interval),
      periodStart,
      periodEnd,
      actorId: actor.userId,
      occurredAt: periodStart,
    });
  } else {
    const upgradeCents =
      existing &&
      existing.status === "active" &&
      isPaidPlan(currentPlan) &&
      isPaidPlan(input.plan)
        ? prorateCents(
            (getPlanLimits(input.plan).priceCentsPerSeatMonthly -
              getPlanLimits(currentPlan).priceCentsPerSeatMonthly) *
              existing.seats *
              monthsInPeriod(existing.interval),
            daysRemaining(now, parseIso(existing.currentPeriodEnd)),
            daysInPeriod(
              parseIso(existing.currentPeriodStart),
              parseIso(existing.currentPeriodEnd),
            ),
          )
        : 0;

    subscription = await subscriptionRepo.updateSubscriptionPlan(
      input.orgId,
      input.plan,
      input.interval,
    );

    if (existing && upgradeCents > 0) {
      await issueSubscriptionInvoice({
        orgId: input.orgId,
        amountCents: upgradeCents,
        periodStart: existing.currentPeriodStart,
        periodEnd: existing.currentPeriodEnd,
        actorId: actor.userId,
        occurredAt: toIsoTimestamp(now),
      });
    }
  }

  await emit("billing.plan_changed", {
    ...actorEnvelope(actor),
    from: currentPlan,
    to: input.plan,
  });

  return subscription;
}

export async function updateSeats(
  actor: Actor,
  input: UpdateSeatsInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const plan = await planFor(input.orgId);

  if (input.seats > getLimit(plan, "seats")) {
    throw new Error(`Plan ${plan} tops out at ${getLimit(plan, "seats")} seats`);
  }

  const existing = await subscriptionRepo.findSubscription(input.orgId);
  const updated = await subscriptionRepo.updateSeatCount(input.orgId, input.seats);

  if (
    existing &&
    existing.status === "active" &&
    isPaidPlan(existing.plan) &&
    input.seats > existing.seats
  ) {
    const now = new Date();
    const full =
      getPlanLimits(existing.plan).priceCentsPerSeatMonthly *
      (input.seats - existing.seats) *
      monthsInPeriod(existing.interval);
    const amountCents = prorateCents(
      full,
      daysRemaining(now, parseIso(existing.currentPeriodEnd)),
      daysInPeriod(
        parseIso(existing.currentPeriodStart),
        parseIso(existing.currentPeriodEnd),
      ),
    );
    await issueSubscriptionInvoice({
      orgId: input.orgId,
      amountCents,
      periodStart: existing.currentPeriodStart,
      periodEnd: existing.currentPeriodEnd,
      actorId: actor.userId,
      occurredAt: toIsoTimestamp(now),
    });
  }

  return updated;
}

